import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import Button from 'flarum/common/components/Button';
import { avatarUser, personName, personUrl, t, tx } from './util';

/**
 * Above the discussion list while a week runs: last week's most-thanked
 * member. Tiny, so it ships in forum.js. Dismissed per week, in this browser.
 */

const KEY = 'ernestdefoe-kudos.banner-dismissed';
function dismissed(week) {
  try {
    return localStorage.getItem(KEY) === week;
  } catch {
    return false;
  }
}
export default class SpotlightBanner extends Component {
  view() {
    const {
      week,
      count,
      user
    } = this.attrs.spotlight;
    if (dismissed(week)) return null;
    const url = personUrl(user);
    const me = app.session.user && Number(app.session.user.id()) === user.id;
    return m("div", {
      className: "KudosBanner",
      role: "note"
    }, m("div", {
      className: "KudosBanner-glow",
      "aria-hidden": "true"
    }), m("span", {
      className: "KudosBanner-avatar"
    }, m(Avatar, {
      user: avatarUser(user)
    }), m("span", {
      className: "KudosBanner-star",
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-star"
    }))), m("div", {
      className: "KudosBanner-text"
    }, m("div", {
      className: "KudosBanner-eyebrow"
    }, t('banner.eyebrow')), m("div", {
      className: "KudosBanner-line"
    }, me ? t('banner.you', {
      count
    }) : t('banner.line', {
      name: url ? m(Link, {
        href: url
      }, personName(user)) : m("strong", null, personName(user)),
      count
    }))), m(Link, {
      className: "Button Button--primary KudosBanner-cta",
      href: app.route('kudos') + '?week=' + week
    }, t('banner.cta')), m(Button, {
      className: "Button Button--icon Button--link KudosBanner-close",
      icon: "fas fa-times",
      "aria-label": tx('banner.dismiss'),
      onclick: () => {
        try {
          localStorage.setItem(KEY, week);
        } catch {}
        m.redraw();
      }
    }));
  }
}